library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity soqpsk_timing_ted is generic(SPS:positive:=8); port(clk,reset,valid:in std_logic; i_in,q_in:in signed(31 downto 0); symbol_tick:out std_logic; error:out signed(31 downto 0)); end;
architecture rtl of soqpsk_timing_ted is signal count:natural range 0 to SPS-1:=0; signal early_i,early_q,mid_i,mid_q:signed(31 downto 0):=(others=>'0'); begin process(clk) variable p0,p1:signed(63 downto 0); variable e:signed(31 downto 0); begin if rising_edge(clk) then symbol_tick<='0'; if reset='1' then count<=0;early_i<=(others=>'0');early_q<=(others=>'0');mid_i<=(others=>'0');mid_q<=(others=>'0');error<=(others=>'0'); elsif valid='1' then if count=0 then early_i<=i_in;early_q<=q_in; elsif count=SPS/2 then mid_i<=i_in;mid_q<=q_in; elsif count=SPS-1 then p0:=mid_i*(i_in-early_i); p1:=mid_q*(q_in-early_q); e:=resize(shift_right(p0+p1,16),32); error<=e; symbol_tick<='1'; end if; if count=SPS-1 then count<=0;else count<=count+1;end if; end if; end if; end process; end;
